CREATE TABLE "subscriber_outbox" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "subscriber_id" BIGINT NOT NULL,
    "kind" TEXT NOT NULL,
    "event_key" TEXT NOT NULL,
    "payload" TEXT,
    "attempts" INTEGER NOT NULL,
    "next_attempt_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "sent_at" TIMESTAMPTZ(6),
    "failed_at" TIMESTAMPTZ(6),
    "last_error" TEXT,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_subscriber_outbox_by_subscriber_id" ON "subscriber_outbox" ("subscriber_id");
CREATE INDEX "index_subscriber_outbox_by_next_attempt_at" ON "subscriber_outbox" ("next_attempt_at");
CREATE TABLE "page_email_settings" (
    "page_id" BIGINT NOT NULL,
    "subscriptions" BOOLEAN NOT NULL,
    "notify_automatic" BOOLEAN NOT NULL,
    "sender_name" TEXT,
    "sender_address" TEXT,
    "reply_to" TEXT,
    "domain_id" TEXT,
    "domain_name" TEXT,
    "domain_status" TEXT,
    "domain_records" TEXT,
    "domain_checked_at" TIMESTAMPTZ(6),
    PRIMARY KEY ("page_id")
);
CREATE TABLE "subscribers" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "page_id" BIGINT NOT NULL,
    "kind" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "email_index" TEXT NOT NULL,
    "webhook_url" TEXT,
    "url_index" TEXT,
    "webhook_secret" TEXT,
    "secret_shown" BOOLEAN NOT NULL,
    "components" TEXT,
    "status" TEXT NOT NULL,
    "link_salt" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "confirmed_at" TIMESTAMPTZ(6),
    "ended_at" TIMESTAMPTZ(6),
    "failures" INTEGER NOT NULL,
    "failing_since" TIMESTAMPTZ(6),
    "last_delivery_at" TIMESTAMPTZ(6),
    "last_error" TEXT,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_subscribers_by_page_id" ON "subscribers" ("page_id");
CREATE INDEX "index_subscribers_by_email_index" ON "subscribers" ("email_index");
CREATE INDEX "index_subscribers_by_url_index" ON "subscribers" ("url_index");
-- Hand-written: email settings and subscribers go with their page, queued
-- messages with their subscriber; the claim query scans only unsent rows.
ALTER TABLE "page_email_settings"
    ADD CONSTRAINT "page_email_settings_page_fk"
    FOREIGN KEY ("page_id") REFERENCES "status_pages" ("id") ON DELETE CASCADE;
ALTER TABLE "subscribers"
    ADD CONSTRAINT "subscribers_page_fk"
    FOREIGN KEY ("page_id") REFERENCES "status_pages" ("id") ON DELETE CASCADE;
ALTER TABLE "subscriber_outbox"
    ADD CONSTRAINT "subscriber_outbox_subscriber_fk"
    FOREIGN KEY ("subscriber_id") REFERENCES "subscribers" ("id") ON DELETE CASCADE;
CREATE INDEX "subscriber_outbox_due"
    ON "subscriber_outbox" ("next_attempt_at", "id")
    WHERE "sent_at" IS NULL AND "failed_at" IS NULL;
CREATE INDEX "subscriber_outbox_by_event" ON "subscriber_outbox" ("subscriber_id", "event_key");
